
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% make_results.m
%
% This pipeline aggregates session-level neural data structures across
% recordings and performs population-level analyses comparing task
% conditions.

% -------------------------------------------------------------------------
% HOW TO RUN THIS SCRIPT:
%
% This script operates on precomputed session-level data structures
% generated by the preprocessing pipeline (build_all_data_structures).
%
% After preprocessing, data must be organized as:
%
%   Exp2/
%       └── Data-Neuro/
%               └── M1/
%                   └── mSTS/
%                       └── All_Data_Structures/
%                           ├── session1.mat
%                           ├── session2.mat
%                           └── ...
%
% To run this analysis, pass the path to the corresponding
% "All_Data_Structures" directory as input:
%
%  results = make_results('your_local_path/Exp2/Data-Neuro/M1/mSTS/All_Data_Structures', 'M1', 'mSTS');
%
% The script must be run separately for each region (e.g., mSTS and aSTS)
% before performing cross-region comparisons.

% -------------------------------------------------------------------------
% NOTE ON TASK NAMING:
% At the data-processing stage, task conditions were labeled as "main"
% and "control" for organizational and file-naming purposes.
%
% In the manuscript and analyses, these conditions correspond to:
%   control  → TD condition
%   main     → PC condition
% -------------------------------------------------------------------------
%
% The script:
%   1) Collects and filters responsive and reliable units across sessions
%   2) Computes population stimulus dissimilarity matrices
%   3) Performs statistical comparisons of neural responses across tasks
%      (all stimuli, preferred stimuli, and empty stimulus)
%   4) Computes and visualizes bootstrapped PSTHs with confidence intervals
%   5) Performs stimulus-ranking analyses using cross-validated responses
%   6) Computes bootstrapped binned response differences between regions
%   7) Saves SVM-ready neural response matrices for decoding analyses
%
% All analyses are performed at the population level and organized by
% monkey and recording region.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% Aggregate session-level data structures and perform population-level
% analyses comparing control and main task conditions for a given region
% and monkey 

function results = make_results(folder_name, monkey_name, region)

    
    % Load and concatenate data across all sessions for the specified monkey
    results = collect_all_sessions(folder_name, monkey_name);

    
    %%%%%%%%%%%%%%% Stimulus dissimilarity analysis %%%%%%%%%%%%%%%%%%%%%%%
    
    % Compute population-level stimulus dissimilarity matrices based on
    % normalized neural response patterns and compare within-task structure


    fprintf('Computing dissimilarity matrix for monkey %s region %s...\n', monkey_name, region);

    [dissimilarity_matrix, dissimilarity_vector, stim_list_control_main] = compute_dissimilarity_matrix(results.all_stimuli_respons_main, results.all_stimuli_respons_control, results.stimlist);
    
    fig_diss = plot_dissimilarity_matrix(dissimilarity_matrix, dissimilarity_vector, stim_list_control_main);
    
    diss_blocks = extract_dissimilarity_blocks(dissimilarity_matrix);
    
    [p_s, h_s, stats_s] = signrank(diss_blocks.control_dist_vector, diss_blocks.main_dist_vector);
    fig_scatter = plot_dissimilarity_scatter(diss_blocks.control_dist_vector, diss_blocks.main_dist_vector, p_s);
    
    %%%%%%%%%%%%%%% Statistical comparison of neural responses %%%%%%%%%%%%  
    % Compare population responses between tasks for:
    %   - all stimuli
    %   - preferred stimuli
    %   - empty stimulus (occluder)

    response_window = 350:549;
    [p, h, stats] = compare_response_windows(results.all_all_stimuli_data_control, results.all_all_stimuli_data_main, response_window);
    
   
    [p_h, h_h, stats_h] = compare_response_windows(results.all_high_stimuli_data_control, results.all_high_stimuli_data_main, response_window);
     

    [p_o, h_o, stats_o] = compare_response_windows(results.all_data_empty_stimulus_control, results.all_data_empty_stimulus_main, response_window);
     
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%% Population PSTHs %%%%%%%%%%%%%%%%%%%%%%
    
    % Compute bootstrapped PSTHs with confidence intervals for control and main
    % tasks, including empty stimulus responses
 
    numBootstrapSamples = 1000;
    bin_size = 10;
    %Mean responses to all stimuli 
    
    fprintf('Computing PSTHs for monkey %s region %s...\n', monkey_name, region);

    psth = compute_bootstrap_psth_2plots(results.all_all_stimuli_data_control, results.all_all_stimuli_data_main, numBootstrapSamples, bin_size, results.all_data_empty_stimulus_control, results.all_data_empty_stimulus_main);
    fig = plot_bootstrap_psth_2plots(psth, p, p_o);
    
    %Mean responses to preffered stimulus
    psth = compute_bootstrap_psth_2plots(results.all_high_stimuli_data_control, results.all_high_stimuli_data_main, numBootstrapSamples, bin_size, results.all_data_empty_stimulus_control, results.all_data_empty_stimulus_main);
    fig_h = plot_bootstrap_psth_2plots(psth, p_h, p_o);
    
    %%%%%%%%%%%%%%%%%%%%% Normalized PSTH analysis %%%%%%%%%%%%%%%%%%%%%%%
    % Normalize responses per unit (using the maximum binned response across
    % all conditions, including empty stimulus(occluder)) to compare time courses of
    % activity between control, main, and empty-stimulus conditions

    psth_norm_a = compute_bootstrap_psth_2plots_with_normalization(results.all_all_stimuli_data_control, results.all_all_stimuli_data_main, numBootstrapSamples, bin_size, results.all_data_empty_stimulus_control, results.all_data_empty_stimulus_main);

    response_bins = 35:55;
    [p_norm_a, h_norm_a, stats_norm_a] = compare_response_windows_normalized_binned(psth_norm_a.unit_binned_control_norm, psth_norm_a.unit_binned_main_norm, response_bins);  
    [p_norm_o, h_norm_o, stats_norm_o] = compare_response_windows_normalized_binned(psth_norm_a.unit_binned_empty_control_norm, psth_norm_a.unit_binned_empty_main_norm, response_bins);  
    fig_norm = plot_normalized_bootstrap_psth_2plots(psth_norm_a, p_norm_a, p_norm_o);


    psth_norm_h = compute_bootstrap_psth_2plots_with_normalization(results.all_high_stimuli_data_control, results.all_high_stimuli_data_main, numBootstrapSamples, bin_size, results.all_data_empty_stimulus_control, results.all_data_empty_stimulus_main);
    [p_norm_h, h_norm_h, stats_norm_h] = compare_response_windows_normalized_binned(psth_norm_h.unit_binned_control_norm, psth_norm_h.unit_binned_main_norm, response_bins);

    fig_norm = plot_normalized_bootstrap_psth_2plots(psth_norm_h, p_norm_h, p_norm_o);


    %%%%%%%%%%%%%%%%%%%%%%%%%%% Stimulus ranking analysis %%%%%%%%%%%%%%%%%
    
    % Perform cross-validated stimulus-ranking analysis to assess population
    % response structure and task-dependent reordering

    
    fprintf('Computing ranking plots for monkey %s region %s...\n', monkey_name, region);
    numBootstrapSamples = 1000;
    baseline_win = 150:349;
    trials_num = 9;
    stim_num = 40;
    rank_stats = compute_ranking_stats( results.all_response_firing_medium_control',  results.all_response_firing_medium_main', results.all_all_stimuli_data_control, results.all_all_stimuli_data_main, stim_num, trials_num, numBootstrapSamples, baseline_win);
    fig_rank = plot_ranking_stats(rank_stats, 'TD', 'PC');

    rank_stats = compute_ranking_stats( results.all_response_firing_medium_main',  results.all_response_firing_medium_control', results.all_all_stimuli_data_control, results.all_all_stimuli_data_main, stim_num, trials_num, numBootstrapSamples, baseline_win);
    fig_rank = plot_ranking_stats(rank_stats, 'PC', 'TD');
    
    
    
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%% Region-difference analysis %%%%%%%%%%%%
    % Compute and save bootstrapped binned response differences between regions 

    
    bin_size = 10;
    out_folder = 'diff_regions_data';

    [all_ready, missing_files] = check_region_diff_files(monkey_name, region, bin_size, out_folder);

    if ~all_ready
        disp(['Region difference files are not available yet. Creating files for region ' char(region) ' ...']);
        disp('Region difference files:')
        disp(missing_files)

        diff_high = compute_bootstrap_binned_difference( results.all_high_stimuli_data_control, results.all_high_stimuli_data_main, 1000, 10);
        diff_all = compute_bootstrap_binned_difference(results.all_all_stimuli_data_control, results.all_all_stimuli_data_main, 1000, 10);
    
        save_region_diff_stats(diff_high, diff_all, monkey_name, region, bin_size, out_folder);
    end     

    %%%%%%%%%%%%%%%%%%%%%%%%%% Save SVM decoding datasets %%%%%%%%%%%%%%%%%
    % Export medium-stimulus responses and binned neural data for decoding analyses

    all_response_firing_medium_control = results.all_response_firing_medium_control';
    all_response_firing_medium_main = results.all_response_firing_medium_main';

    out_folder = 'svm_data';

    if ~exist(out_folder, 'dir')
        mkdir(out_folder);
    end
    
    headers = results.all_channels_names';
    file_name = fullfile(out_folder, ...
        [char(results.monkey_name), '_', char(region), '_all_response_firing_medium_TD.csv']);
    writecell([headers; num2cell(all_response_firing_medium_control)], file_name);
    
    headers = results.all_channels_names';
    file_name = fullfile(out_folder, ...
        [char(results.monkey_name), '_', char(region), '_all_response_firing_medium_PC.csv']);
    writecell([headers; num2cell(all_response_firing_medium_main)], file_name);


    %%%%%%%%%%%%%%%% Save SVM decoding datasets (binned data) %%%%%%%%%%%%%
   
    out_folder = 'svm_data';

    if ~exist(out_folder, 'dir')
        mkdir(out_folder);
    end
    
    file_name_control = fullfile(out_folder, ...
        [char(results.monkey_name), '_', char(region), '_all_data_res_window_bins_18_TD.mat']);
    all_data_res_window_bins_control = results.all_data_res_window_bins_control;
    save(file_name_control, 'all_data_res_window_bins_control');
    
    file_name_main = fullfile(out_folder, ...
        [char(results.monkey_name), '_', char(region), '_all_data_res_window_bins_18_PC.mat']);
    all_data_res_window_bins_main = results.all_data_res_window_bins_main;
    save(file_name_main, 'all_data_res_window_bins_main');
    
    file_name_control_svm2 = fullfile(out_folder, ...
        [char(results.monkey_name), '_', char(region), '_all_data_res_window_bins_25_TD.mat']);
    all_data_res_window_bins_control_svm2 = results.all_data_res_window_bins_control_svm2;
    save(file_name_control_svm2, 'all_data_res_window_bins_control_svm2');
    
    file_name_main_svm2 = fullfile(out_folder, ...
        [char(results.monkey_name), '_', char(region), '_all_data_res_window_bins_25_PC.mat']);
    all_data_res_window_bins_main_svm2 = results.all_data_res_window_bins_main_svm2;
    save(file_name_main_svm2, 'all_data_res_window_bins_main_svm2');


end
 

function results = collect_all_sessions(folder_name, monkey_name)

    % -------------------- file list --------------------
    mat_files = dir(fullfile(folder_name, '*.mat'));
    loaded_structures = {};

    % -------------------- initialize variables --------------------
    all_channels = [];
    all_channels_names = [];
    all_mean_response_main = [];
    all_mean_response_control = [];
    all_reliability_control = [];
    all_reliability_main = [];
    channels_main = [];
    channels_control = [];
    interested_channels_control = [];
    interested_channels_main = [];
    all_stimuli_respons_control = [];
    all_stimuli_respons_main = [];
    all_high_stimuli_response_control = [];
    all_high_stimuli_response_main = [];
    all_high_stimuli_data_control = [];
    all_high_stimuli_data_main = [];
    all_all_stimuli_data_control = [];
    all_all_stimuli_data_main = [];
    all_data_empty_stimulus_control=[];
    all_data_empty_stimulus_main = [];
    all_response_firing_medium_control = [];
    all_response_firing_medium_main = [];
    all_data_res_window_bins_control = [];
    all_data_res_window_bins_main = [];
    all_data_res_window_bins_control_svm2 = [];
    all_data_res_window_bins_main_svm2 = [];
    all_interested_channels = {};

    % -------------------- loop through files --------------------
    ch=1;
    for i = 1:length(mat_files)
        file_path = fullfile(folder_name, mat_files(i).name);
        loaded_data = load(file_path);

        loaded_structures{i} = loaded_data;

        parts = strsplit(loaded_data.data_struct.data_name, '_');
        last_part = parts{end};
        interested_Task = last_part;

        disp(loaded_data.data_struct.data_name);

        all_channels = 1:length(loaded_data.data_struct.channel_names);

        %%%%%%%%%%%%%%%%%%%%%%%%% interested_channels %%%%%%%%%%%%%%%%%%%%%
        
        if interested_Task == "control"
            interested_channels_control = loaded_data.data_struct.channels_above_z4;

            mean_response_control = loaded_data.data_struct.mean_response_all_stimuli(all_channels);
            reliability_control = loaded_data.data_struct.reliability(all_channels);
            stimuli_respons_control = loaded_data.data_struct.mean_response;
            high_stimuli_response_control = loaded_data.data_struct.high_stimuli_response;
            data_high_stimuli_control = loaded_data.data_struct.data_high_stimuli;
            data_all_stimuli_control = loaded_data.data_struct.all_stimuli_response;
            %data_all_stimuli_control = loaded_data.data_struct.data_all_stimuli;
            response_firing_medium_control = loaded_data.data_struct.response_firing_medium_stimuli;
            %response_firing_medium_control = loaded_data.data_struct.response_firing_model;
            data_empty_stimulus_control = loaded_data.data_struct.data_empty_stimulus;
            data_res_window_bins_control = loaded_data.data_struct.data_res_window_bins;
            data_res_window_bins_control_svm2 = loaded_data.data_struct.data_res_window_bins_svm2;

        end

        if interested_Task == "main"
            interested_channels_main = loaded_data.data_struct.channels_above_z4;

            mean_response_main = loaded_data.data_struct.mean_response_all_stimuli(all_channels);
            reliability_main = loaded_data.data_struct.reliability(all_channels);
            stimuli_respons_main = loaded_data.data_struct.mean_response;
            high_stimuli_response_main = loaded_data.data_struct.high_stimuli_response;
            data_high_stimuli_main = loaded_data.data_struct.data_high_stimuli;
            data_all_stimuli_main = loaded_data.data_struct.all_stimuli_response;
            %data_all_stimuli_main = loaded_data.data_struct.data_all_stimuli;
            response_firing_medium_main = loaded_data.data_struct.response_firing_medium_stimuli;
            %response_firing_medium_main = loaded_data.data_struct.response_firing_model;
            data_empty_stimulus_main = loaded_data.data_struct.data_empty_stimulus;
            data_res_window_bins_main = loaded_data.data_struct.data_res_window_bins;
            data_res_window_bins_main_svm2 = loaded_data.data_struct.data_res_window_bins_svm2;
            



            if isfield(loaded_data.data_struct, 'stimlist')
                stimlist = loaded_data.data_struct.stimlist;
            else
                disp('stimlist does not exist.');
            end
        end

        if ~isempty(interested_channels_control) && ~isempty(interested_channels_main)
            interested_chann = union(interested_channels_main, interested_channels_control);

             channels_rel_control = find(reliability_control >= 0.5);
             channels_rel_main = find(reliability_main >= 0.5);
             interested_chann_main = intersect(interested_channels_main, channels_rel_main);
             interested_chann_control = intersect(interested_channels_control, channels_rel_control);
             interested_channels = union(interested_chann_main, interested_chann_control);
            
            %new method for having unoits that are passed the ANOVA test
            %and z-score without those are reliable and passed kruskal
            %wallis

            % intrested_channel_with_rel = load ('M2_aSTS_all_interested_channels.mat');
            % intrested_channel_with_rel_per_day = intrested_channel_with_rel.all_interested_channels{ch};
            % disp(intrested_channel_with_rel_per_day);
            % 
            % interested_channels = setdiff(interested_chann,intrested_channel_with_rel_per_day, 'stable') ;
            % disp(interested_channels);

            

            all_channel_idx = [];

            for k = 1:length(interested_channels)
                channel_idx = find(all_channels == interested_channels(k));
                all_channel_idx = [all_channel_idx, channel_idx];
            end


            all_mean_response_main = [all_mean_response_main; mean_response_main(all_channel_idx)'];
            all_mean_response_control = [all_mean_response_control; mean_response_control(all_channel_idx)'];

            channel_names = cellstr(loaded_data.data_struct.channel_names);
            channels = channel_names(all_channel_idx);
            all_channels_names = [all_channels_names; channels];

            all_reliability_control = [all_reliability_control; reliability_control(all_channel_idx)'];
            all_reliability_main = [all_reliability_main; reliability_main(all_channel_idx)'];

            all_high_stimuli_response_control = [all_high_stimuli_response_control; high_stimuli_response_control(all_channel_idx)'];
            all_high_stimuli_response_main = [all_high_stimuli_response_main; high_stimuli_response_main(all_channel_idx)'];

            all_high_stimuli_data_control = [all_high_stimuli_data_control; data_high_stimuli_control(all_channel_idx, :)];
            all_high_stimuli_data_main = [all_high_stimuli_data_main; data_high_stimuli_main(all_channel_idx, :)];

            all_all_stimuli_data_control = [all_all_stimuli_data_control; data_all_stimuli_control(all_channel_idx, :)];
            all_all_stimuli_data_main = [all_all_stimuli_data_main; data_all_stimuli_main(all_channel_idx, :)];
            
            all_response_firing_medium_control = [all_response_firing_medium_control; response_firing_medium_control(:, all_channel_idx)'];
            all_response_firing_medium_main = [all_response_firing_medium_main; response_firing_medium_main(:, all_channel_idx)'];

            all_stimuli_respons_control = [all_stimuli_respons_control; stimuli_respons_control(:, all_channel_idx)'];
            all_stimuli_respons_main = [all_stimuli_respons_main; stimuli_respons_main(:, all_channel_idx)'];

            all_data_empty_stimulus_control = [all_data_empty_stimulus_control; data_empty_stimulus_control( all_channel_idx, :)]; 
            all_data_empty_stimulus_main = [all_data_empty_stimulus_main; data_empty_stimulus_main( all_channel_idx, :)]; 

            all_data_res_window_bins_control = cat(3, all_data_res_window_bins_control, data_res_window_bins_control(:,:,all_channel_idx));
            all_data_res_window_bins_main = cat(3, all_data_res_window_bins_main, data_res_window_bins_main(:,:,all_channel_idx));
%            all_data_res_window_bins_control_svm2 = cat(3, all_data_res_window_bins_control_svm2, data_res_window_bins_control_svm2(:,:,all_channel_idx));
        %    all_data_res_window_bins_main_svm2 = cat(3, all_data_res_window_bins_main_svm2, data_res_window_bins_main_svm2(:,:,all_channel_idx));




            all_interested_channels = [all_interested_channels; interested_channels(:)'];
            all_interested_channels{end+1,1} = interested_channels(:)';
            save('M1_aSTS_all_interested_channels_without_rel.mat', 'all_interested_channels')


            mean_response_control = [];
            mean_response_main = [];
            interested_channels_control = [];
            interested_channels_main = [];
            all_channels = [];
            interested_channels = [];
            data_high_stimuli_control = [];
            data_high_stimuli_main = [];
            data_all_stimuli_control = [];
            data_all_stimuli_main = [];
            data_empty_stimulus_control = [];
            data_empty_stimulus_main = [];
            data_res_window_bins_main = [];
            data_res_window_bins_control = [];
            data_res_window_bins_main_svm2 = [];
            data_res_window_bins_control_svm2 = [];

            ch=ch+2;
        end
        
    end
    

    % -------------------- save outputs in struct --------------------
    results.folder_name = folder_name;
    results.monkey_name = monkey_name;
    results.loaded_structures = loaded_structures;

    results.all_channels = all_channels;
    results.all_channels_names = all_channels_names;
    results.all_mean_response_main = all_mean_response_main;
    results.all_mean_response_control = all_mean_response_control;
    results.all_reliability_control = all_reliability_control;
    results.all_reliability_main = all_reliability_main;
    results.channels_main = channels_main;
    results.channels_control = channels_control;
    results.all_stimuli_respons_control = all_stimuli_respons_control;
    results.all_stimuli_respons_main = all_stimuli_respons_main;
    results.all_high_stimuli_response_control = all_high_stimuli_response_control;
    results.all_high_stimuli_response_main = all_high_stimuli_response_main;
    results.all_high_stimuli_data_control = all_high_stimuli_data_control;
    results.all_high_stimuli_data_main = all_high_stimuli_data_main;
    results.all_all_stimuli_data_control = all_all_stimuli_data_control;
    results.all_all_stimuli_data_main = all_all_stimuli_data_main;
    results.all_data_empty_stimulus_control = all_data_empty_stimulus_control;
    results.all_data_empty_stimulus_main = all_data_empty_stimulus_main;    
    results.all_response_firing_medium_control = all_response_firing_medium_control;
    results.all_response_firing_medium_main = all_response_firing_medium_main;
    results.all_data_res_window_bins_control = all_data_res_window_bins_control;
    results.all_data_res_window_bins_main = all_data_res_window_bins_main;
    results.all_data_res_window_bins_control_svm2 = all_data_res_window_bins_control_svm2;
    results.all_data_res_window_bins_main_svm2 = all_data_res_window_bins_main_svm2;
    results.all_interested_channels = all_interested_channels;

    if exist('stimlist', 'var')
        results.stimlist = stimlist;
    else
        results.stimlist = [];
    end
end


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%% Functions %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% Generate bootstrapped resamples of a data matrix by sampling rows
% with replacement
function [bootSamples] = bootstrap_rows(data, numBootstrapSamples)
     [numRows, numCols] = size(data);
     
     bootSamples = zeros(numBootstrapSamples, numRows, numCols);
     
     for i = 1:numBootstrapSamples
         % Randomly sample row indices with replacement
         sampledIndices = randi(numRows, numRows, 1); 
         bootSamples(i, :, :) = data(sampledIndices, :); 
     end
 end

 
 % Compute a stimulus dissimilarity matrix based on correlation distance (1 - correlation)
 % between normalized population response vectors for control and main tasks

 function [dissimilarity_matrix, dissimilarity_vector, stim_list_control_main] = compute_dissimilarity_matrix(all_stimuli_respons_main, all_stimuli_respons_control, stimlist)

    all_control_main_stimuli_responses = [all_stimuli_respons_main, all_stimuli_respons_control];

    row_max = max(all_control_main_stimuli_responses, [], 2);
    normalized_matrix = all_control_main_stimuli_responses ./ row_max;

    transposed_responses = normalized_matrix';
    dissimilarity_vector = pdist(transposed_responses, 'correlation');
    dissimilarity_matrix = squareform(dissimilarity_vector);

    if stimlist(16) == "Empty"
    stimlist(16) = []; 
    end

    stim_list_control_main = [stimlist, stimlist];
end


function fig = plot_dissimilarity_matrix(dissimilarity_matrix, dissimilarity_vector, stim_list_control_main)

    fig = figure('Color','w');
    ax = axes(fig);

    % Heatmap
    imagesc(ax, dissimilarity_matrix);
    axis(ax, 'image');
    axis(ax, 'tight');
    set(ax, 'YDir','reverse');
    colormap(ax, parula);

    % Robust max for colorbar
    valid_vals = dissimilarity_vector(~isnan(dissimilarity_vector));
    if isempty(valid_vals)
        max_l = 1;
    else
        max_l = max(valid_vals);
        if max_l <= 0
            max_l = 1;
        end
    end
    caxis(ax, [0 max_l]);

    % Labels
    labels = string(stim_list_control_main);

    if any(contains(labels, "_"))
        short_labels = extractBefore(labels, "_");
        short_labels(short_labels == "") = labels(short_labels == "");
    else
        short_labels = labels;
    end

    G = 5;
    n = numel(short_labels);

    centers = abs(G/2) : G : (n - G/2 + 2);
    group_labels = short_labels(1:G:n);

    ax.XTick = centers;
    ax.YTick = centers;
    ax.XTickLabel = group_labels;
    ax.YTickLabel = group_labels;
    xtickangle(ax, 50);

    hold(ax,'on');
    group = 40;
    bounds = group + 0.5 : G : group + 0.5;
    for b = bounds
        xline(ax, b, '-', 'Color',[0 0 0 0.25], 'LineWidth',0.8, 'HandleVisibility','off');
