% Extract within-task and between-task dissimilarity blocks and convert
% them into vectorized forms for statistical analysis

function blocks = extract_dissimilarity_blocks(dissimilarity_matrix)

    N = size(dissimilarity_matrix, 1) / 2;

    if mod(N, 1) ~= 0
        error('Matrix size is not divisible by 2 — check input size!');
    end

    main_within = dissimilarity_matrix(1:N, 1:N);
    control_within = dissimilarity_matrix(N+1:end, N+1:end);
    between = dissimilarity_matrix(1:N, N+1:end);

    blocks.main_within = main_within;
    blocks.control_within = control_within;
    blocks.between = between;

    blocks.main_dist_vector = squareform(main_within);
    blocks.control_dist_vector = squareform(control_within);
    blocks.between_dist_vector = between(:);

    blocks.between_diag = diag(between);

    n = size(between, 1);
    between_vector = [];

    for i = 1:n-1
        between_vector = [between_vector, between(i, i+1:n)];
    end

    blocks.between_vector = between_vector(:);
end

% Compare summed neural responses across tasks within a specified
% response window using signrank test 

function [p, h, stats] =  compare_response_windows(stimuli_data_control, stimuli_data_main, response_window)

    all_stimuli_response_windows_control = stimuli_data_control(:, response_window);
    all_stimuli_response_windows_main = stimuli_data_main(:, response_window);

    all_stimuli_sum_response_control = sum(all_stimuli_response_windows_control, 2);
    all_stimuli_sum_response_main = sum(all_stimuli_response_windows_main, 2);

    [p, h, stats] = signrank(all_stimuli_sum_response_control, all_stimuli_sum_response_main);
end

function [p, h, stats] = compare_response_windows_normalized_binned( binned_data_control_norm, binned_data_main_norm, response_bins)

   
    all_stimuli_response_windows_control = binned_data_control_norm(:, response_bins);
    all_stimuli_response_windows_main    = binned_data_main_norm(:, response_bins);

    all_stimuli_sum_response_control = sum(all_stimuli_response_windows_control, 2);
    all_stimuli_sum_response_main    = sum(all_stimuli_response_windows_main, 2);

    [p, h, stats] = signrank( ...
        all_stimuli_sum_response_control, ...
        all_stimuli_sum_response_main);
end
 

% Compute bootstrapped population PSTHs and confidence intervals by
% resampling units and temporally binning spike responses

function psth = compute_bootstrap_psth(all_all_stimuli_data_control, all_all_stimuli_data_main, numBootstrapSamples, bin_size)

    mean_condition_control = mean(all_all_stimuli_data_control, 1);
    mean_condition_main = mean(all_all_stimuli_data_main, 1);

    bootedData_control = bootstrap_rows(all_all_stimuli_data_control, numBootstrapSamples);
    bootedData_main = bootstrap_rows(all_all_stimuli_data_main, numBootstrapSamples);

    bootedData_control_mean = zeros(numBootstrapSamples, size(all_all_stimuli_data_control, 2));
    bootedData_main_mean = zeros(numBootstrapSamples, size(all_all_stimuli_data_main, 2));

    for k = 1:numBootstrapSamples
        bootedData_control_mean(k, :) = mean(squeeze(bootedData_control(k, :, :)), 1);
        bootedData_main_mean(k, :) = mean(squeeze(bootedData_main(k, :, :)), 1);
    end

    ci_control = prctile(bootedData_control_mean, [2.5, 97.5], 1);
    ci_main = prctile(bootedData_main_mean, [2.5, 97.5], 1);

    num_bins = floor(size(mean_condition_control, 2) / bin_size);

    binned_data_control = zeros(1, num_bins);
    binned_data_main = zeros(1, num_bins);
    binned_ci_control_lower = zeros(1, num_bins);
    binned_ci_control_upper = zeros(1, num_bins);
    binned_ci_main_lower = zeros(1, num_bins);
    binned_ci_main_upper = zeros(1, num_bins);

    for bin = 1:num_bins
        bin_start = (bin - 1) * bin_size + 1;
        bin_end = bin_start + bin_size - 1;

        binned_data_control(bin) = sum(mean_condition_control(bin_start:bin_end));
        binned_data_main(bin) = sum(mean_condition_main(bin_start:bin_end));

        binned_ci_control_lower(bin) = sum(ci_control(1, bin_start:bin_end));
        binned_ci_control_upper(bin) = sum(ci_control(2, bin_start:bin_end));
        binned_ci_main_lower(bin) = sum(ci_main(1, bin_start:bin_end));
        binned_ci_main_upper(bin) = sum(ci_main(2, bin_start:bin_end));
    end

    psth.binned_data_control = binned_data_control;
    psth.binned_data_main = binned_data_main;
    psth.binned_ci_control_lower = binned_ci_control_lower;
    psth.binned_ci_control_upper = binned_ci_control_upper;
    psth.binned_ci_main_lower = binned_ci_main_lower;
    psth.binned_ci_main_upper = binned_ci_main_upper;
    psth.num_bins = num_bins;
    psth.n_units = size(all_all_stimuli_data_control, 1);
end

