function psth = compute_bootstrap_psth_2plots(data_control, data_main, numBootstrapSamples, bin_size, data_empty_control, data_empty_main)

    if nargin < 5
        data_empty_control = [];
        data_empty_main = [];
    end

    % ---------------- main conditions ----------------
    mean_condition_control = mean(data_control, 1);
    mean_condition_main = mean(data_main, 1);

    bootedData_control = bootstrap_rows(data_control, numBootstrapSamples);
    bootedData_main = bootstrap_rows(data_main, numBootstrapSamples);

    bootedData_control_mean = zeros(numBootstrapSamples, size(data_control, 2));
    bootedData_main_mean = zeros(numBootstrapSamples, size(data_main, 2));

    for k = 1:numBootstrapSamples
        bootedData_control_mean(k, :) = mean(squeeze(bootedData_control(k, :, :)), 1);
        bootedData_main_mean(k, :) = mean(squeeze(bootedData_main(k, :, :)), 1);
    end

    ci_control = prctile(bootedData_control_mean, [2.5, 97.5], 1);
    ci_main = prctile(bootedData_main_mean, [2.5, 97.5], 1);

    % ---------------- optional empty conditions ----------------
    has_empty = ~isempty(data_empty_control) && ~isempty(data_empty_main);

    if has_empty
        mean_empty_condition_control = mean(data_empty_control, 1);
        mean_empty_condition_main = mean(data_empty_main, 1);

        bootedData_empty_control = bootstrap_rows(data_empty_control, numBootstrapSamples);
        bootedData_empty_main = bootstrap_rows(data_empty_main, numBootstrapSamples);

        bootedData_empty_control_mean = zeros(numBootstrapSamples, size(data_empty_control, 2));
        bootedData_empty_main_mean = zeros(numBootstrapSamples, size(data_empty_main, 2));

        for k = 1:numBootstrapSamples
            bootedData_empty_control_mean(k, :) = mean(squeeze(bootedData_empty_control(k, :, :)), 1);
            bootedData_empty_main_mean(k, :) = mean(squeeze(bootedData_empty_main(k, :, :)), 1);
        end

        ci_empty_control = prctile(bootedData_empty_control_mean, [2.5, 97.5], 1);
        ci_empty_main = prctile(bootedData_empty_main_mean, [2.5, 97.5], 1);
    end

    % ---------------- binning ----------------
    num_bins = floor(size(mean_condition_control, 2) / bin_size);

    psth.binned_data_control = zeros(1, num_bins);
    psth.binned_data_main = zeros(1, num_bins);
    psth.binned_ci_control_lower = zeros(1, num_bins);
    psth.binned_ci_control_upper = zeros(1, num_bins);
    psth.binned_ci_main_lower = zeros(1, num_bins);
    psth.binned_ci_main_upper = zeros(1, num_bins);

    if has_empty
        psth.binned_empty_data_control = zeros(1, num_bins);
        psth.binned_empty_data_main = zeros(1, num_bins);
        psth.binned_empty_ci_control_lower = zeros(1, num_bins);
        psth.binned_empty_ci_control_upper = zeros(1, num_bins);
        psth.binned_empty_ci_main_lower = zeros(1, num_bins);
        psth.binned_empty_ci_main_upper = zeros(1, num_bins);
    end

    for bin = 1:num_bins
        bin_start = (bin - 1) * bin_size + 1;
        bin_end = bin_start + bin_size - 1;

        psth.binned_data_control(bin) = sum(mean_condition_control(bin_start:bin_end));
        psth.binned_data_main(bin) = sum(mean_condition_main(bin_start:bin_end));

        psth.binned_ci_control_lower(bin) = sum(ci_control(1, bin_start:bin_end));
        psth.binned_ci_control_upper(bin) = sum(ci_control(2, bin_start:bin_end));
        psth.binned_ci_main_lower(bin) = sum(ci_main(1, bin_start:bin_end));
        psth.binned_ci_main_upper(bin) = sum(ci_main(2, bin_start:bin_end));

        if has_empty
            psth.binned_empty_data_control(bin) = sum(mean_empty_condition_control(bin_start:bin_end));
            psth.binned_empty_data_main(bin) = sum(mean_empty_condition_main(bin_start:bin_end));

            psth.binned_empty_ci_control_lower(bin) = sum(ci_empty_control(1, bin_start:bin_end));
            psth.binned_empty_ci_control_upper(bin) = sum(ci_empty_control(2, bin_start:bin_end));
            psth.binned_empty_ci_main_lower(bin) = sum(ci_empty_main(1, bin_start:bin_end));
            psth.binned_empty_ci_main_upper(bin) = sum(ci_empty_main(2, bin_start:bin_end));
        end
    end

    psth.num_bins = num_bins;
    psth.n_units = size(data_control, 1);
    psth.has_empty = has_empty;
end


% Compute normalized bootstrapped population PSTHs and confidence intervals by
% temporally binning unit responses, normalizing each unit by its maximum
% response across conditions, and resampling units
function psth = compute_bootstrap_psth_2plots_with_normalization(data_control, data_main, numBootstrapSamples, bin_size, data_empty_control, data_empty_main)

    if nargin < 5
        data_empty_control = [];
        data_empty_main = [];
    end

    has_empty = ~isempty(data_empty_control) && ~isempty(data_empty_main);

    time_window = 1:min(700, size(data_control, 2));
    n_units = size(data_control, 1);
    num_bins = floor(size(data_control(:, time_window), 2) / bin_size);

    % ---------------------------------------------------------
    % 1) Bin each unit separately
    % Result: units x bins
    % ---------------------------------------------------------
    binned_control = bin_units(data_control(:, time_window), bin_size);
    binned_main    = bin_units(data_main(:, time_window), bin_size);

    % disp('binned_control_shape:');
    % disp(size(binned_control));

    if has_empty
        binned_empty_control = bin_units(data_empty_control(:, time_window), bin_size);
        binned_empty_main    = bin_units(data_empty_main(:, time_window), bin_size);
        % disp('binned_empty_control_shape:')
        % disp(size(binned_empty_control));
    end

    

    % ---------------------------------------------------------
    % 2) Find normalization value for each unit separately
    %
    % For each unit:
    %   max_control       = max bin of control
    %   max_main          = max bin of main
    %   max_empty_control = max bin of empty control
    %   max_empty_main    = max bin of empty main
    %
    % Then:
    %   norm_value = max of those 4 values
    % ---------------------------------------------------------
    if has_empty
        norm_value_per_unit = max([ ...
            max(binned_control, [], 2), ...
            max(binned_main, [], 2), ...
            max(binned_empty_control, [], 2), ...
            max(binned_empty_main, [], 2) ...
        ], [], 2);
    else
        norm_value_per_unit = max([ ...
            max(binned_control, [], 2), ...
            max(binned_main, [], 2) ...
        ], [], 2);
    end
    % disp("norm_value_per_unit:")
    % disp(norm_value_per_unit);

    % Avoid division by zero
    norm_value_per_unit(norm_value_per_unit == 0 | isnan(norm_value_per_unit)) = 1;

    % ---------------------------------------------------------
    % 3) Normalize all 4 binned matrices using the same value
    % for each unit
    % ---------------------------------------------------------
    binned_control_norm = binned_control ./ norm_value_per_unit;
    binned_main_norm    = binned_main    ./ norm_value_per_unit;

    if has_empty
        binned_empty_control_norm = binned_empty_control ./ norm_value_per_unit;
        binned_empty_main_norm    = binned_empty_main    ./ norm_value_per_unit;
    end
    
    
    % ---------------------------------------------------------
    % 4) Compute population mean after normalization
    % ---------------------------------------------------------
    psth.binned_data_control = mean(binned_control_norm, 1);
    psth.binned_data_main    = mean(binned_main_norm, 1);


    % ---------------------------------------------------------
    % 5) Bootstrap CI on normalized binned unit-level data
    % ---------------------------------------------------------

    ci_control = bootstrap_ci_units(binned_control_norm, numBootstrapSamples);
    ci_main    = bootstrap_ci_units(binned_main_norm, numBootstrapSamples);

    psth.binned_ci_control_lower = ci_control(1, :);
    psth.binned_ci_control_upper = ci_control(2, :);

    psth.binned_ci_main_lower = ci_main(1, :);
    psth.binned_ci_main_upper = ci_main(2, :);

    if has_empty
        psth.binned_empty_data_control = mean(binned_empty_control_norm, 1);
        psth.binned_empty_data_main    = mean(binned_empty_main_norm, 1);

        ci_empty_control = bootstrap_ci_units(binned_empty_control_norm, numBootstrapSamples);
        ci_empty_main    = bootstrap_ci_units(binned_empty_main_norm, numBootstrapSamples);

        psth.binned_empty_ci_control_lower = ci_empty_control(1, :);
        psth.binned_empty_ci_control_upper = ci_empty_control(2, :);

        psth.binned_empty_ci_main_lower = ci_empty_main(1, :);
        psth.binned_empty_ci_main_upper = ci_empty_main(2, :);
    end

    % ---------------------------------------------------------
    % 6) Save useful information
    % ---------------------------------------------------------
    psth.num_bins = num_bins;
    psth.n_units = n_units;
    psth.has_empty = has_empty;

    psth.unit_binned_control_norm = binned_control_norm;
    psth.unit_binned_main_norm = binned_main_norm;
    psth.normalization_value_per_unit = norm_value_per_unit;

    if has_empty
        psth.unit_binned_empty_control_norm = binned_empty_control_norm;
        psth.unit_binned_empty_main_norm = binned_empty_main_norm;
    end
end


function binned_data = bin_units(data, bin_size)

    n_units = size(data, 1);
    num_bins = floor(size(data, 2) / bin_size);

    data = data(:, 1:num_bins * bin_size);

    data_reshaped = reshape(data, n_units, bin_size, num_bins);
    binned_data = reshape(sum(data_reshaped, 2), n_units, num_bins);
end

function ci = bootstrap_ci_units(unit_binned_data, numBootstrapSamples)

    n_units = size(unit_binned_data, 1);
    num_bins = size(unit_binned_data, 2);

    boot_means = zeros(numBootstrapSamples, num_bins);

    for k = 1:numBootstrapSamples
        sampled_units = randi(n_units, [n_units, 1]);
        boot_means(k, :) = mean(unit_binned_data(sampled_units, :), 1);
    end

    ci = prctile(boot_means, [2.5, 97.5], 1);
end


